"""All-Pairs Shortest Path — Floyd-Warshall.

`k` must be the outer loop: after iteration k, dist[i][j] is optimal among paths
whose intermediate nodes all come from {0..k}.

Time: O(n^3)   Space: O(n^2)
"""
from typing import List


class Solution:
    def allPairsShortestPath(self, n: int, edges: List[List[int]]) -> List[List[int]]:
        INF = float("inf")
        dist = [[0 if i == j else INF for j in range(n)] for i in range(n)]
        for u, v, w in edges:
            dist[u][v] = min(dist[u][v], w)

        for k in range(n):
            row_k = dist[k]
            for i in range(n):
                via = dist[i][k]
                if via == INF:
                    continue
                row_i = dist[i]
                for j in range(n):
                    if via + row_k[j] < row_i[j]:
                        row_i[j] = via + row_k[j]

        return [[-1 if value == INF else value for value in row] for row in dist]
